CREATE TABLE IF NOT EXISTS mcp_stdio_states (variant_id VARCHAR(36), member_id VARCHAR(36) DEFAULT '', team_id VARCHAR(36) NOT NULL, process_key VARCHAR(64) NOT NULL, `state` VARCHAR(16) NOT NULL, failure_code VARCHAR(32) NULL, changed_at BIGINT NOT NULL, CONSTRAINT pk_mcp_stdio_states PRIMARY KEY (variant_id, member_id), CONSTRAINT fk_mcp_stdio_states_variant_id__id FOREIGN KEY (variant_id) REFERENCES variants(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_mcp_stdio_states_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX mcp_stdio_state_team ON mcp_stdio_states (team_id);